{
  "name": "化学气相沉积工艺控制系统",
  "name_en": "Chemical Vapor Deposition Process Control System",
  "manufacturer": "",
  "description": "用于化学气相沉积（CVD）实验的工艺控制系统，通常配合反应腔、加热炉和多路气体流量控制部件使用。它用于设置与执行沉积配方、调整温度和气体流量参数，并监看工艺过程中的趋势变化，适合薄膜生长与材料制备实验。",
  "description_en": "A chemical vapor deposition (CVD) process control system used with a reactor chamber, heater or furnace, and multiple gas flow control components. It is used to define and run deposition recipes, adjust temperature and gas flow parameters, and monitor process trends during thin-film growth and materials synthesis experiments.",
  "tag_hints": [
    "CVD",
    "thin film deposition",
    "recipe execution",
    "gas flow control",
    "furnace temperature control",
    "process monitoring"
  ],
  "actions": [
    {
      "action_name": "auto-return_ui_fields",
      "description": "读取当前CVD工艺中已配置的参数字段与设定值。",
      "description_en": "Retrieve the currently configured parameter fields and setpoints for the CVD process."
    },
    {
      "action_name": "auto-save_recipe",
      "description": "保存当前沉积工艺配方，供后续重复调用。",
      "description_en": "Save the current deposition recipe for later reuse."
    },
    {
      "action_name": "auto-open_recipe",
      "description": "打开并载入已保存的工艺配方到系统中。",
      "description_en": "Open and load a previously saved process recipe into the system."
    },
    {
      "action_name": "auto-update_plot",
      "description": "刷新工艺过程趋势图，例如气体流量随时间的变化曲线。",
      "description_en": "Refresh the process trend plot, such as gas flow versus time."
    },
    {
      "action_name": "auto-start_recipe",
      "description": "启动并执行当前设定的CVD工艺配方。",
      "description_en": "Start and execute the currently configured CVD process recipe."
    },
    {
      "action_name": "auto-stop_recipe",
      "description": "停止当前正在执行的工艺配方。",
      "description_en": "Stop the process recipe that is currently running."
    },
    {
      "action_name": "auto-apply_setpoints",
      "description": "应用当前配置的工艺设定值，例如温度和气体流量参数。",
      "description_en": "Apply the currently configured process setpoints, such as temperature and gas flow parameters."
    }
  ]
}
